const modal=document.querySelector('#modal');document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>modal.classList.add('open'));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.classList.remove('open'));modal?.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});document.querySelector('[data-send]')?.addEventListener('click',()=>{modal.classList.remove('open');document.querySelector('#toast').classList.add('show');setTimeout(()=>document.querySelector('#toast').classList.remove('show'),2600)});
